def transform(grid):
    h, w = len(grid), len(grid[0])
    component = [[-1] * w for _ in range(h)]
    component_count = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or component[r][c] != -1:
                continue
            component[r][c] = component_count
            queue = deque([(r, c)])
            while queue:
                row, col = queue.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = row + dr, col + dc
                    if (0 <= nr < h and 0 <= nc < w
                            and grid[nr][nc] == 1 and component[nr][nc] == -1):
                        component[nr][nc] = component_count
                        queue.append((nr, nc))
            component_count += 1

    outside = [[False] * w for _ in range(h)]
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not outside[nr][nc]):
                outside[nr][nc] = True
                queue.append((nr, nc))

    enclosing_components = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not outside[r][c]:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                            enclosing_components.add(component[nr][nc])

    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            enclosed = not outside[r][c]
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and component[nr][nc] in enclosing_components):
                        result[r][c] = 3 if enclosed else 2
                        break
                if result[r][c] in (2, 3):
                    break
    return result
